#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int dem = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (x == 2) dem++;
    }
    printf("%d\n", dem);
    return 0;
}
